/**
 * ============================================================================
 *  AETHERION — AUTONOMY & INTERNAL POLITICS  (the vassal rulebook)
 * ============================================================================
 *  The single source of truth for what a subordinate polity can and cannot do.
 *  sovereignty.json (generated by scripts/etl/build-sovereignty.mjs from Natural
 *  Earth) maps each dependency ADM0_A3 → its sovereign + an autonomy TIER; this
 *  file gives every tier its CONTROL MATRIX (develop / police / military /
 *  diplomacy) plus the tunables for the two independence paths and for province
 *  unrest → insurgency. Pure logic that reads this lives in sim/sovereignty.ts,
 *  sim/independence.ts and sim/unrest.ts. No hard-coded rules in components.
 */
import sovereigntyJson from './sovereignty.json';

/** INTEGRAL = a fully sovereign state (the default; not stored in the JSON). */
export type AutonomyTier =
  | 'INTEGRAL'
  | 'CONSTITUENT_COUNTRY'
  | 'FREE_ASSOCIATION'
  | 'OVERSEAS_TERRITORY'
  | 'MILITARY_LEASE';

/** What a polity of a given tier may do itself vs. what its sovereign handles. */
export interface Controls {
  develop: boolean; // build province development slots
  police: boolean; // internal security / counter-insurgency
  military: 'full' | 'militia' | 'none'; // raise armed forces
  diplomacy: 'full' | 'limited' | 'none'; // conduct its own foreign relations
  inheritsWars: boolean; // dragged into the sovereign's wars/alliances
}

export interface TierDef {
  label: string;
  short: string;
  blurb: string;
  controls: Controls;
  /** Baseline unrest pressure this tier adds (neglected territories simmer). */
  unrestBias: number; // 0..1
  /** How readily a peaceful referendum is granted (0 = never, 1 = trivially). */
  independenceEase: number; // 0..1
}

